      {%- endif %}
      {%- if m.teacher %}
      {{ m.teacher_x }}
      {%- endif %}
      {%- if m.duration %}
      {{ m.duration }}
      {%- endif %}
      {%- if m.licence %}
      {{ m.attribution }} ({{ m.licence.name }}, {{ m.licence.url }})
      {%- endif %}
      false

{%- endfor %}
